// CSD_RATIONALE_BEGIN
// Math-word-problem CSD. The strategy generates a step-by-step solution with
// symbolic expressions and the final answer wrapped in << >> delimiters.
//
// State tracked:
//   - generated: full visible output including delimiter tokens
//   - insideConstrainedOut: whether we are inside a << >> span
//   - currentConstrainedOut: tokens accumulated inside the current span
//   - steps/cost: token budget consumed
//
// Decision logic:
//   Outside a span: generate freely with UnconstrainedStep. When "<<" appears,
//   enter constrained mode (either observed or forced after preamble).
//   Inside a span: if the parser accepts the current constrained prefix as
//   complete, close the span with CloseSpanIfComplete. Otherwise, use
//   AdaptiveConstrainedStep with the caller-supplied token groups for soft
//   preference while the parser enforces hard validity. This handles both
//   intermediate symbolic expressions (e.g., "3 + 4 = 7") and the final
//   numeric answer inside << >>.
//
// The task requires visible << >> delimiters, so we use OpenConstrainedSpan /
// EnterObservedConstrainedSpan and CloseConstrainedSpan / CloseSpanIfComplete.
// We append task guidance once at the start to steer the model toward the
// step-by-step + delimited-answer format.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   1. Outside-span branch (next == "<<"):
//      We set currentConstrainedOut := [] which satisfies parser.IsValidPrefix([])
//      by the method precondition. insideConstrainedOut becomes true only then.
//   2. CloseSpanIfComplete branch:
//      When closed == true, insideConstrainedOut becomes false making the
//      implication vacuously true. When closed == false, generated/inside/current
//      are unchanged, so the invariant is preserved trivially.
//   3. AdaptiveConstrainedStep + AppendConstrainedToken branch:
//      AdaptiveConstrainedStep returns either EOS or a parser-valid next token
//      (by its contract). AppendConstrainedToken extends currentConstrainedOut
//      with a parser-valid token, preserving IsValidPrefix by the parser's
//      prefix-extension property.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Outside-span: steps += 1; generated grows by at most 1 (the non-EOS token
//   appended). So |generated| <= |generatedPrefix| + steps is preserved.
//   CloseSpanIfComplete: steps += 1; CloseSpanIfComplete appends at most ">>"
//   (1 token) to generated, so growth is at most 1 per step.
//   Constrained step: steps += 1; AppendConstrainedToken appends exactly 1
//   token to generated (EOS causes break without appending). Bound preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math problem step by step. Wrap each symbolic expression and the final answer inside << >> delimiters. For example: The cost is <<3 * 4 = 12>> dollars, so the answer is <<12>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Math-word-problem CSD with strict final-answer span control.
//
// Key insights from failure analysis:
// 1. The model was generating malformed content inside << >> spans (using {var}
//    template syntax, ** operator, etc.) because constrained generation wasn't
//    being applied effectively.
// 2. The primary failure is "syntax_valid_semantic_mismatch" (26/49) - model
//    produces syntactically valid spans but wrong answers, often because it
//    generates the wrong formula or includes invalid characters.
// 3. Unclosed spans (3/49) occurred when the model hit EOS mid-span.
// 4. The constrained intervention activity was near-zero (7/49 examples), meaning
//    the parser was barely being used.
//
// Strategy:
// - Generate freely with UnconstrainedChunk until "<<" is observed.
// - Once inside a span, use hard constrained generation (ConstrainedStep) to
//   ensure only parser-valid tokens are emitted.
// - After each constrained token, check CloseSpanIfComplete to close as soon
//   as the parser accepts the expression.
// - Use CloseSpanWithinBudget as a safety net if the span budget is running low.
// - For the final answer span, use SafeRepetitionPenaltyStep to avoid repeating
//   content from earlier in the output.
// - Strong task guidance directs the model to emit only numeric expressions
//   inside << >> without template variables like {n} or {var}.
//
// The key fix: instead of letting unconstrained generation produce the span
// content (which allowed malformed expressions), we switch to ConstrainedStep
// inside every span. This ensures parser validity at every token position.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   1. Outside-span branch (UnconstrainedChunk):
//      When stoppedOnOpenSpan is true, generatedOut already ends with "<<" and
//      we call EnterObservedConstrainedSpan which sets currentConstrainedOut := []
//      (valid by precondition parser.IsValidPrefix([])). When stoppedOnEos or
//      neither delimiter was seen, insideConstrainedOut remains false, making
//      the implication vacuous.
//   2. CloseSpanIfComplete branch (inside span):
//      When closed == true, insideConstrainedOut becomes false (implication
//      vacuously true, currentConstrainedOut cleared to []). When closed == false,
//      generated/inside/current are unchanged and the invariant is trivially
//      preserved.
//   3. ConstrainedStep + AppendConstrainedToken branch:
//      ConstrainedStep returns either EOS or a token t such that
//      parser.IsValidPrefix(currentConstrainedOut + [t]) holds (by ConstrainedStep
//      contract). AppendConstrainedToken sets currentConstrainedOut :=
//      currentConstrainedOut + [t], which is parser-valid. EOS causes break
//      without any state mutation.
//   4. CloseSpanWithinBudget branch (safety net):
//      By its postcondition: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//      This directly satisfies the invariant.
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   Outside-span (UnconstrainedChunk): stepsUsed is the actual budget consumed,
//   and generatedOut grows by at most stepsUsed tokens (EOS and open-span
//   delimiter are counted but visible growth is bounded by stepsUsed). We add
//   stepsUsed to steps.
//   CloseSpanIfComplete: costs +1 step, appends at most ">>" (1 token). Preserved.
//   ConstrainedStep + AppendConstrainedToken: costs +1 step, appends exactly 1
//   token (or 0 on EOS break). Preserved.
//   CloseSpanWithinBudget: costs at most closeBudget steps, appends at most
//   closeBudget tokens. We add closeBudget to steps, bounding |generated|.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve step by step. For EACH intermediate calculation and the final numeric answer, write exactly one expression inside << >>. Inside << >> use ONLY numbers and operators + - * / // % ( ) int. NO variables like {n}, NO ** operator, NO curly braces. Final answer must be a single number expression like <<42>> or <<3*4+2>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Generate freely until we see "<<" or EOS
    var chunkBudget := maxSteps - steps;
    if chunkBudget > 40 {
      chunkBudget := 40;
    }
    var generatedOut, stoppedOnOpenSpan, stoppedOnEos, stepsUsed :=
      helpers.UnconstrainedChunk(lm, prompt, generated, chunkBudget, "<<", eosToken);
    steps := steps + stepsUsed;
    generated := generatedOut;
    if stoppedOnEos {
      break;
    }
    if stoppedOnOpenSpan {
      // "<<" is already in generatedOut; enter constrained mode without adding another delimiter
      var g2, i2, c2 := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := g2;
      insideConstrainedOut := i2;
      currentConstrainedOut := c2;
    }
  } else {
    // Inside a constrained span
    // First check if we can close cleanly
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      // If budget is very low, use CloseSpanWithinBudget as safety net
      var remainingBudget := maxSteps - steps;
      if remainingBudget <= 5 && remainingBudget > 0 {
        var sg, si, sc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
        );
        generated := sg;
        insideConstrainedOut := si;
        currentConstrainedOut := sc;
        steps := steps + remainingBudget;
      } else {
        // Use hard constrained step to ensure only parser-valid tokens
        var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
        if next == eosToken {
          // Safety: try to close the span before breaking
          if maxSteps - steps > 0 {
            var sg2, si2, sc2 := helpers.CloseSpanWithinBudget(
              lm, parser, prompt, generated, currentConstrainedOut, eosToken, 1
            );
            generated := sg2;
            insideConstrainedOut := si2;
            currentConstrainedOut := sc2;
            steps := steps + 1;
          }
          break;
        } else {
          var ag, ai, ac := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        }
      }
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Math-word-problem CSD with improved span management.
//
// Key analysis from failure modes:
// 1. Attempt 2 (0% accuracy): The constrained generation was working but
//    the task guidance caused the model to reason about "no variables" rule,
//    leading to unterminated spans (model fills span with reasoning text about
//    the constraint). 20 examples hit runtime errors (CSD exceeded max_steps:
//    generated 907 tokens > 900) - the unconstrained chunk was consuming too
//    much budget.
//
// 2. Attempt 1 (28.6% accuracy, 81.6% syntax): Simple approach worked better.
//    Failures: 23 syntax_valid_semantic_mismatch (model gets right structure
//    but wrong answer), 7 token_budget_exhausted.
//
// Root causes to fix:
// A) Unterminated spans: Model generates reasoning inside << >> and hits EOS
//    or dead-end before closing. Fix: Use CloseSpanWithinBudget as safety net
//    when budget runs low.
// B) Budget exhaustion: Model reasons too long in unconstrained mode. Fix: 
//    Limit unconstrained chunk size per iteration to conserve budget.
// C) Wrong answers: Model generates syntactically valid but semantically wrong
//    expressions. Fix: Use SafeRepetitionPenaltyStep inside spans to avoid
//    repeating tokens, and use AdaptiveConstrainedStep with groups.
// D) No spans emitted (21 examples in attempt 2): Guidance caused model to
//    refuse. Fix: Use minimal guidance that doesn't confuse the model.
//
// Strategy: Build on Attempt 1 (best result) with targeted improvements:
// 1. Keep simple free generation until "<<" appears
// 2. Inside spans: use CloseSpanIfComplete first, then AdaptiveConstrainedStep
// 3. Add CloseSpanWithinBudget safety net when budget is low (< 20 steps)
// 4. Use minimal, non-confusing task guidance
// 5. Cap unconstrained steps per iteration at 30 to preserve budget
//
// The key insight: the parser enforces hard validity on span content.
// The model's free-text reasoning outside spans is left unconstrained.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   1. Outside-span branch (UnconstrainedStep):
//      When next == "<<", we set currentConstrainedOut := [] which satisfies
//      parser.IsValidPrefix([]) by the method precondition. insideConstrainedOut
//      becomes true only in this case. For all other tokens, insideConstrainedOut
//      remains false making the implication vacuous.
//   2. CloseSpanIfComplete branch:
//      When closed == true: CloseSpanIfComplete sets insideConstrainedOut := false
//      and currentConstrainedOut := [], making the implication vacuously true.
//      When closed == false: state is unchanged, invariant trivially preserved.
//   3. AdaptiveConstrainedStep + AppendConstrainedToken branch:
//      AdaptiveConstrainedStep returns either EOS or a token t such that
//      parser.IsValidPrefix(currentConstrainedOut + [t]) holds. AppendConstrainedToken
//      sets currentConstrainedOut := currentConstrainedOut + [t], preserving validity.
//      EOS causes break without state mutation.
//   4. CloseSpanWithinBudget branch (safety net):
//      By its postcondition: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//      This directly satisfies the invariant.
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   Outside-span: steps += 1; generated grows by at most 1 (non-EOS token
//   appended or nothing on EOS break). Preserved.
//   CloseSpanIfComplete: steps += 1; appends at most ">>" (1 token). Preserved.
//   AdaptiveConstrainedStep + AppendConstrainedToken: steps += 1; AppendConstrainedToken
//   appends exactly 1 token to generated (EOS causes break without appending). Preserved.
//   CloseSpanWithinBudget: steps += closeBudget (at most maxSteps - steps);
//   generatedOut grows by at most closeBudget tokens. Since steps becomes
//   steps + closeBudget <= maxSteps, bound is preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve step by step. Write each calculation result and the final answer inside << >> delimiters. Example: <<3 * 4>> gives <<12>>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    // Safety net: if budget is very low, use CloseSpanWithinBudget
    var remainingBudget := maxSteps - steps;
    if remainingBudget <= 15 && remainingBudget > 0 {
      var sg, si, sc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
      );
      generated := sg;
      insideConstrainedOut := si;
      currentConstrainedOut := sc;
      steps := steps + remainingBudget;
    } else {
      // Try to close if complete
      var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
      steps := steps + 1;
      if closed {
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
      } else {
        var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next := helpers.AdaptiveConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut,
          validTokenGroups, 4.0, narrowThreshold, eosToken
        );
        if next == eosToken {
          // Try to close the span before giving up
          var remainingBudget2 := maxSteps - steps;
          if remainingBudget2 > 0 {
            var sg2, si2, sc2 := helpers.CloseSpanWithinBudget(
              lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget2
            );
            generated := sg2;
            insideConstrainedOut := si2;
            currentConstrainedOut := sc2;
            steps := steps + remainingBudget2;
          }
          break;
        } else {
          var ag, ai, ac := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        }
      }
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Deep analysis of failures:
// 1. 25/49 examples have correct syntax but wrong answers - the model generates
//    valid expressions but computes wrong formulas (e.g., `n * frac` vs `int(n * frac)`,
//    `(w1+w2+w3)*price` vs `(w1+w2+(n-2)*w3)*price`).
// 2. 10/49 have malformed constrained content - model generates things like
//    `{total}`, `cur{cost}`, `**` inside spans.
// 3. Key insight: "Constrained intervention activity" shows only 6/49 examples
//    used constrained decoding - the model is generating spans entirely in free text
//    before the constrained step triggers, or the "<<" is generated as free text
//    and the strategy doesn't intercept it.
//
// The core problem: the model generates the FINAL answer span containing the
// formula in FREE TEXT mode (UnconstrainedStep), not in constrained mode.
// This means the parser never enforces valid expression syntax on the span content.
// 
// Root cause: with UnconstrainedStep generating tokens, "<<" appears in generated
// but the NEXT token after "<<" is the formula content - which gets generated in
// the NEXT call to UnconstrainedStep. The strategy only flips to constrained mode
// AFTER seeing "<<", so the content of the span is generated freely.
//
// Wait - looking again at the code, when next == "<<" is detected, insideConstrainedOut
// becomes true, and then the NEXT iteration should be constrained. So why is it failing?
// Answer: "constrained intervention activity: examples_without_activity 43/49"
// The spans are opened by UnconstrainedStep, but most examples never trigger the
// constrained branch because the model generates "<<formula>>" as a single
// UnconstrainedStep? No - tokens are individual.
//
// Actually the issue is: the model generates "<<" then immediately generates ">>"
// in the next unconstrained step (closing the span without entering constrained mode),
// OR the model's output has "<<" appear but the span content is so short that
// CloseSpanIfComplete triggers immediately without generating constrained content.
//
// Looking at diagnostic: "Top helper calls: UnconstrainedStep=17314, ...
//  CloseConstrainedSpan=7, AdaptiveConstrainedStep=13"
// With 49 examples and ~350 tokens/example, most tokens are generated via
// UnconstrainedStep. Only 13 AdaptiveConstrainedStep calls happened total!
//
// The real issue: when the strategy detects "<<" via UnconstrainedStep, it enters
// constrained mode. But then CloseSpanIfComplete is called, and it costs 1 step
// and returns closed=false (since currentConstrained==[] and parser may not be
// complete at []), so then we call AdaptiveConstrainedStep. But the model has
// already generated the formula in the unconstrained chunk! 
//
// No wait - the tokens in "generated" after unconstrained steps include the 
// formula tokens. But currentConstrained only has tokens generated after "<<" 
// was detected. So the formula tokens inside << >> from UnconstrainedStep aren't
// in currentConstrained at all - they're in generated as free text.
//
// Solution approach: Use UnconstrainedChunk to detect "<<" opening, then once
// inside constrained mode, generate the ENTIRE span content under parser control.
// The key is: when UnconstrainedChunk stops on "<<" (stoppedOnOpenSpan=true),
// use EnterObservedConstrainedSpan to set state, then use constrained generation
// for the formula.
//
// But the bigger issue is accuracy. The model generates wrong formulas.
// The evaluator extracts "last_visible_span" - the final << >> span.
// The correct answers require exact Python-style expressions with int(), //, etc.
// The parser should be enforcing this, but it's not being used.
//
// New strategy:
// 1. Use UnconstrainedChunk to generate reasoning text until "<<" appears
// 2. Once "<<" is detected, enter constrained mode
// 3. Generate the span content under hard parser control
// 4. When complete, close the span
// 5. Continue until budget or EOS
//
// For accuracy: The model needs to generate correct formulas. The task prompt
// guidance should instruct the model about the exact format needed.
// Looking at correct answers: int(), //, %, * are all valid. The parser enforces
// the grammar for these expressions.
//
// Critical insight from failing examples:
// - "n - n * frac" vs correct "n - int(n * frac)" - needs int() wrapping
// - "(k1+k2)/(n1+n2)*100" vs "int(100*(k1+k2)/(n1+n2))" - needs int() and order
// - "cur{cost}" - model generating template variables in spans
//
// The parser should reject "{", "}", "{n}" etc. inside spans.
// But the model generates these in FREE TEXT mode, not constrained mode!
//
// Core fix: Force all span content to go through parser-controlled generation.
// Use UnconstrainedChunk with "<<" as the open delimiter to stop before/at "<<",
// then use ConstrainedGeneration for the span content.
//
// Additional fix for accuracy: Guide the model to use int() for integer operations
// and // for integer division. This is a semantic guidance issue.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   1. UnconstrainedChunk branch (outside span): When stoppedOnOpenSpan=true,
//      we call EnterObservedConstrainedSpan which sets insideConstrainedOut=true
//      and currentConstrainedOut=[], which satisfies parser.IsValidPrefix([])
//      by precondition. When stoppedOnOpenSpan=false, insideConstrainedOut
//      remains false making the implication vacuous.
//   2. CloseSpanIfComplete branch: When closed=true, insideConstrainedOut becomes
//      false, making the implication vacuously satisfied. When closed=false,
//      state is unchanged, invariant preserved.
//   3. AdaptiveConstrainedStep + AppendConstrainedToken branch: AdaptiveConstrainedStep
//      returns either EOS or a parser-valid next token t such that
//      parser.IsValidPrefix(currentConstrainedOut + [t]). AppendConstrainedToken
//      sets currentConstrainedOut := currentConstrainedOut + [t], preserving validity.
//      EOS causes break without state mutation.
//   4. CloseSpanWithinBudget branch (safety net): By its postcondition,
//      insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut),
//      directly satisfying the invariant.
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   UnconstrainedChunk: steps += stepsUsed; generatedOut = generated extended by
//   at most stepsUsed tokens. By UnconstrainedChunk's postcondition,
//   |generatedOut| <= |generated| + stepsUsed. Preserved.
//   CloseSpanIfComplete: steps += 1; appends at most ">>" (1 token). Preserved.
//   AdaptiveConstrainedStep + AppendConstrainedToken: steps += 1; AppendConstrainedToken
//   appends exactly 1 token to generated. Preserved.
//   CloseSpanWithinBudget: steps += closeBudget; by its postcondition,
//   |generatedOut| <= |generated| + closeBudget. Preserved.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve this math problem step by step. Show your reasoning, then place ONLY the final numeric expression inside << >>. Use int() for integer results, // for integer division. Example: <<int(n * 3 // 2)>>. Keep span content concise - one expression only.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var narrowThreshold: nat := 16;
var chunkSize: nat := 40;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Use UnconstrainedChunk to generate free text and detect "<<" 
    var remainingSteps := maxSteps - steps;
    var actualChunk := if remainingSteps < chunkSize then remainingSteps else chunkSize;
    if actualChunk == 0 {
      break;
    }
    var generatedOut, stoppedOnOpenSpan, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, actualChunk, "<<", eosToken
    );
    steps := steps + stepsUsed;
    generated := generatedOut;
    if stoppedOnEos {
      break;
    } else if stoppedOnOpenSpan {
      // "<<" was already appended to generated by UnconstrainedChunk
      // Use EnterObservedConstrainedSpan to set state without appending another "<<"
      var g2, i2, c2 := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := g2;
      insideConstrainedOut := i2;
      currentConstrainedOut := c2;
    }
    // If neither stopped on open span nor EOS, chunk ran to completion without "<<"
    // Continue generating
  } else {
    // We're inside a constrained span
    var remainingBudget := maxSteps - steps;

    // Safety net: if budget is very low, use CloseSpanWithinBudget
    if remainingBudget <= 20 && remainingBudget > 0 {
      var sg, si, sc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
      );
      generated := sg;
      insideConstrainedOut := si;
      currentConstrainedOut := sc;
      steps := steps + remainingBudget;
